    if (DSB(DS_001028DB) != 0u && !(mut & C3B_Q_PAUSE)) return 0u;
    u32 now = DSD(DS_00101500);
    const u8 *p = (const u8 *)res_resolve(h);
    if (p == NULL) return 1u;
    u32 size = DSD((u32)(p - mem));
    u32 cand = 0u;
    int fast = size > 0x6000u;
