    out[0] = 0x000DE114u + c * ((mut & C3B_T_O0) ? 12u : 11u);
    out[1] = 0x000A3528u + c * ((mut & C3B_T_O1) ? 16u : 20u);
    out[2] = 0x000A6728u + c * ((mut & C3B_T_O2) ? 4u : 6u);
