        if (mut & 0x80000u) hit_anim_start_a(rec, stream, 0x3F800000u);  /* @a: 0x3C480 for 0x3C520 */
        else hit_anim_start_c(rec, stream, (mut & 0x2000000u) ? 0x40000000u : 0x3F800000u);   /* @hold */
