    if (!M(5)) a &= 0xFFu;                                                   /* @alflag: the whole EAX */
    if (a == 0u && !M(6)) DSD(b + 0x24u) = DSD(b + 0x28u);                   /* @nocopy */
    a = (u32)ai_ready(M(7) ? q : p);                                         /* @rside */
