    u32 r1 = DSD((mut == 2u) ? DS_001077B8 : DS_0010784C);                   /* @rec1 */
    u32 i0 = (mut == 3u) ? DSD(r0 + 0x56u) : (u32)DSW(r0 + 0x56u);           /* @idxw */
    u32 i1 = (mut == 4u) ? (u32)DSW(r1 + 0x54u) : (u32)DSW(r1 + 0x56u);      /* @idxoff */
