    self = ctx[2];
    if ((DSB(self + 0x40u) & 0x80u) != 0) return 0u;
    cmd = DSW(0x001088E0u + side * 2u);
    if ((cmd & 0x8000u) == 0) return 0u;
    rec = DSD(0x001077B0u + side * 0x94u);
    DSW(rec + 0x34u) = 0;
    DSB(rec + 0x43u) = 0;
    DSB(rec + 0x42u) = 0;
    DSB(self + 0x5Fu) = 0xFFu;
