        if (mut != 11u) camera_box_clip((mut == 12u) ? side : other, DSD(DS_00100AF0 + other * 4u), bb);   /* @noclipb @clipbside */
        if (mut == 13u) for (u32 i = 0u; i < 4u; i++) bb[i] = DSB(box_o + i);   /* @preclipb */
