    DSD(DS_00100B0C) = d5b_17580_scale(DSD(DS_00100B0C), 0xF3Du, mut);
    DSD(DS_00100B00) = d5b_17580_scale(DSD(DS_00100B00), (mut == 11u) ? 0xF3Du : 0xD56u, mut);   /* @k00 */
    DSD(DS_00100B04) = d5b_17580_scale(DSD(DS_00100B04), 0xD56u, mut);
