    if (mut != 8u) DSD(DS_00100AF8) = 0u;                                    /* @noaf8 */
    if (mut != 9u) DSD(DS_00100AFC) = 0u;                                    /* @noafc */
    if (mut != 21u) d5b_17580_scales(mut);                                   /* @late: scaled after the overlap test */
